function tick(now){const delta=last?Math.min(.05,(now-last)/1000):0;last=now;frame++;premium.update(['paused','ready'].includes(game.state)?0:delta);if(game.state==='playing'){const d=(keys.has(bindings.left)||keys.has('ArrowLeft')&&!Object.values(bindings).includes('ArrowLeft')?-1:0)+(keys.has(bindings.right)||keys.has('ArrowRight')&&!Object.values(bindings).includes('ArrowRight')?1:0);game.move(touchMove||d,delta,false,settings.controlMode!=='precision');const elevation=(keys.has(bindings.aimDown)?1:0)-(keys.has(bindings.aimUp)?1:0);if(elevation){manualAimUntil=game.time+1.5;game.adjustAimElevation(elevation,delta);}game.update(delta);if(game.flowCheckpoint){checkpoint=game.flowCheckpoint;game.flowCheckpoint=null;safeSave();}if(settings.controlMode==='flow'&&game.state==='playing'){const direct=aimPadPointer!==null||game.time<manualAimUntil;if(!direct&&game.time>=assistAt){assistTarget=game.assistAim(settings.smartWeapon);assistAt=game.time+.12;setWeapon(game.weapon);}if(settings.autoFire&&(game.operation||direct||assistTarget?.aligned))game.fire();}if(game.operation&&settings.controlMode!=='flow'&&settings.autoFire&&game.state==='playing')game.fire();if((settings.holdFire&&aimPointer!==null)||firePointer!==null||keys.has(bindings.fire))assistedFire();}sounds();endingPlayer.update(delta);if(endingPlayer.active){endingVoice.update(endingPlayer.elapsed,endingPlayer.lastShot);endingSound.update(endingPlayer.elapsed,endingPlayer.lastShot,endingVoice.active);}else{if(endingSound.running)endingSound.stop();if(endingVoice.enabled)endingVoice.stop();}if(game.state==='intermission'&&shownDraftWave!==game.wave){shownDraftWave=game.wave;showTuning();}if(game.state==='won'||game.state==='lost')finalize();if(now>toastExpires)$('toast').classList.remove('visible');const radio=$('radioLine');if(radio)radio.hidden=!game.continuous||game.time>=radioUntil||!['playing','paused'].includes(game.state);if(!endingPlayer.active){draw();drawRadar();}if(preparationOpen&&preparePreview?.isConnected&&!$('overlay').classList.contains('hidden')&&premium.actor?.status().ready){const paint=preparePreview.getContext('2d');paint.setTransform(2,0,0,2,0,0);paint.clearRect(0,0,350,180);paint.save();paint.translate(150-game.player.x*1.4,172-(game.player.y+31)*1.4);paint.scale(1.4,1.4);premium.actor.draw(paint,game.player,game.player.x,game.player.y+31,game.time,game.player.life,game.weapon,game.launchGeometry());paint.restore();}if(frame%4===0)hud();requestAnimationFrame(tick);}

