$('resumeRun').addEventListener('click',()=>{if(!resumeCandidate){if(game.state==='paused'){veteranMode=game.veteran;closeLobby();game.pause();hideOverlay();}return;}const recovered=resumeCandidate;veteranMode=recovered.veteran;recovered.operation=true;recovered.pulseStyle=recovered.pulseStyle||'rapid';resumeCandidate=null;mode='chapter';lab=false;closeLobby();setupStage(recovered.config.id,false,recovered.seed);game=recovered;hideOverlay();shownDraftWave=game.wave;setWeapon(game.weapon);hud();if(game.continuous){game.chooseTuning(game.draft[0]);hideOverlay();announceStory();}else showTuning();});
